package com.focusflow.controller; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/recommendations") @CrossOrigin(origins="*") public class RecommendationController{ @GetMapping public List<Map<String,Object>> get(@RequestParam(defaultValue="Programming")String interest){return List.of(card("Programming","Java in 15 minutes","https://www.youtube.com/watch?v=eIrMbAQSU34","Learning"),card("AI","Machine Learning explained visually","https://www.youtube.com/results?search_query=machine+learning+for+beginners","Learning"),card("English","5-minute English speaking practice","https://www.youtube.com/results?search_query=english+speaking+practice","Learning"),card("Finance","Personal finance basics","https://www.youtube.com/results?search_query=personal+finance+basics","Learning"));} private Map<String,Object>card(String i,String t,String u,String c){Map<String,Object>m=new LinkedHashMap<>();m.put("interest",i);m.put("title",t);m.put("url",u);m.put("category",c);return m;}}